    // clang-format on

    static constexpr s32 sShineTableSize = hk::util::arraySize(sShineTable);

    // Returns the ShineEntry for a given uniqueId and stage name,
    // or nullptr if not found. Stage disambiguates the rare uid collisions.
    inline const ShineEntry* findEntry(s32 uid, const char* stage) {
        for (s32 i = 0; i < sShineTableSize; i++) {
            const ShineEntry& e = sShineTable[i];
            if (e.uid == uid && strcmp(e.stage, stage) == 0)
                return &e;
        }
        return nullptr;
    }

    // Returns the ShineEntry at a given flat index (for shuffle/remap).
    inline const ShineEntry* entryAt(s32 index) {
        if (index < 0 || index >= sShineTableSize)
            return nullptr;
        return &sShineTable[index];
    }

    inline s32 findIndex(const ShineEntry* entry) {
        if (!entry)
            return -1;
        for (s32 i = 0; i < sShineTableSize; i++) {
            const ShineEntry& e = sShineTable[i];
            if (&e == entry || (e.uid == entry->uid && strcmp(e.stage, entry->stage) == 0))
                return i;
        }
        return -1;
    }

    inline s32 findIndex(s32 uid, const char* stage) {
        if (!stage)
            return -1;
        for (s32 i = 0; i < sShineTableSize; i++) {
            if (sShineTable[i].uid == uid && strcmp(sShineTable[i].stage, stage) == 0)
                return i;
        }
        return -1;
    }

    // Returns the placement objId for a given uid+stage, or -1 if not found.
    inline s32 findObjId(s32 uid, const char* stage) {
        for (s32 i = 0; i < sShineTableSize; i++) {
            if (sShineTable[i].uid == uid && strcmp(sShineTable[i].stage, stage) == 0)
                return sShineTable[i].objId;
        }
        return -1;
    }

    // Returns the uniqueId for a given stage+objId, or -1 if not found.
    inline s32 findUid(const char* stage, s32 objId) {
        for (s32 i = 0; i < sShineTableSize; i++) {
            if (sShineTable[i].objId == objId && strcmp(sShineTable[i].stage, stage) == 0)
                return sShineTable[i].uid;
        }
        return -1;
    }
    static const char16* getWorldNameFromId(s32 id) {
        if (!WorldMeta::getByWorldId(id))
            Randomizer::logPush("Error getting World Name for ID: %d", id);
        return WorldMeta::getDisplayName16ForWorldId(id);
    }

